Given an array arr[] of size n containing integers, the task is to find the length of the longest subarray having sum equal to the given value k.Note: If there is no subarray with sum equal to k, return 0.Examples: Input: arr[] = [10, 5, 2, 7, 1, -10], k = 15Output: 6Explanation: Subarrays with sum = 15 are [5, 2, 7, 1], [10, 5] and [10, 5, 2, 7, 1, -10]. The length of the longest subarray with a sum of 15 is 6.Input: arr[] = [-5, 8, -14, 2, 4, 12], k = -5Output: 5Explanation: Only subarray with sum = 15 is [-5, 8, -14, 2, 4] of length 5.Input: arr[] = [10, -10, 20, 30], k = 5Output: 0Explanation: No subarray with sum = 5 is present in arr[].Try It YourselfTable of Content[Naive Approach] Using Nested Loop - O(n^2) Time and O(1) Space[Expected Approach] Using Hash Map and Prefix Sum - O(n) Time and O(n) Space[Naive Approach] Using Nested Loop - O(n^2) Time and O(1) SpaceThe idea is to check the sum of all the subarrays and return the length of the longest subarray having the sum k.
            C++

    // C++ program to find the length of the longest
// subarray having sum k using nested loop
#include <iostream>
#include <vector>
using namespace std;

// Function to find longest sub-array having sum k
int longestSubarray(vector<int>& arr, int k) {
    int res = 0;

    for (int i = 0; i < arr.size(); i++) {

        // Sum of subarray from i to j
        int sum = 0;
        for (int j = i; j < arr.size(); j++) {
            sum += arr[j];

          	// If subarray sum is equal to k
            if (sum == k) {

              	// find subarray length and update result
              	int subLen = j - i + 1;
                res = max(res, subLen);
            }
        }
    }

    return res;
}

int main() {
    vector<int> arr = {10, 5, 2, 7, 1, -10};
    int k = 15;
    cout << longestSubarray(arr, k) << endl;
    return 0;
}


