    int res = 0;

    for (int i = 0; i < n; i++) {

        // Sum of subarray from i to j
        int sum = 0;
        for (int j = i; j < n; j++) {
            sum += arr[j];

            // If subarray sum is equal to k
            if (sum == k) {

                // Find subarray length and update result
                int subLen = j - i + 1;
                res = (res > subLen) ? res : subLen;
            }
        }
    }

    return res;
}

